#!/bin/bash
# ncu of the slab-mode x / y passes (one slab of the warm-up forward and inverse), application replay, no cache flush
SP=/tmp/claude-1000/-home-turbotage-Documents-GitHub-HastyCompute/c25caa1d-d864-44cf-9019-66f29ac9cb24/scratchpad
B=${B:-/home/turbotage/Documents/GitHub/HastyCompute/rustlib/target/release/examples/bfp_fft_bench}
M=gpu__time_duration.sum,dram__bytes_read.sum,dram__bytes_write.sum,lts__t_bytes.sum,lts__t_sectors_op_read.sum,lts__t_sectors_op_write.sum,lts__t_sector_op_read_hit_rate.pct,lts__t_sector_op_write_hit_rate.pct,l1tex__t_requests_pipe_lsu_mem_global_op_ld.sum,l1tex__t_sectors_pipe_lsu_mem_global_op_ld.sum,l1tex__t_requests_pipe_lsu_mem_global_op_st.sum,l1tex__t_sectors_pipe_lsu_mem_global_op_st.sum,sm__throughput.avg.pct_of_peak_sustained_elapsed,lts__throughput.avg.pct_of_peak_sustained_elapsed,dram__throughput.avg.pct_of_peak_sustained_elapsed,l1tex__throughput.avg.pct_of_peak_sustained_elapsed,smsp__inst_executed.sum,sm__warps_active.avg.pct_of_peak_sustained_active,l1tex__data_bank_conflicts_pipe_lsu_mem_shared.sum,smsp__issue_active.avg.pct_of_peak_sustained_active,launch__occupancy_limit_shared_mem,launch__shared_mem_per_block_dynamic,lts__d_sectors_fill_sysmem.sum,lts__t_sectors_srcunit_tex_op_read_lookup_miss.sum,lts__t_sectors_srcunit_tex_op_write_lookup_miss.sum
tag=$1; shift
flock $SP/gpu.lock /usr/local/cuda/bin/ncu --replay-mode application --cache-control ${CC:-none} --metrics $M "$@" --csv $B 320 320 320 256 256 256 24 --once ${ST:+--store $ST} ${SLAB:+--slab $SLAB} > $SP/ncu_cz/$tag.csv 2> $SP/ncu_cz/$tag.err
